callbackProcs.Body:
switch -- $method {
  xConnect {
    return "CREATE TABLE t1(a, b, c, d, expr)"
  }

  xBestIndex {
    set COL(0) a
    set COL(1) b
    set COL(2) c
    set COL(3) d
    set COL(4) expr

    set OP(eq) =
    set OP(ne) !=
    set OP(gt) >
    set OP(le) <=
    set OP(lt) <
    set OP(ge) >=
    set OP(match) MATCH
    set OP(like) LIKE
    set OP(glob) GLOB
    set OP(regexp) REGEXP

    set hdl [lindex $args 0]
    set clist [$hdl constraints]

    set ret [list]
    set elist [list]
    set i 0
    foreach c $clist {
      array set C $c
      if {$C(usable)} {
        lappend ret omit $i
        lappend elist "$COL($C(column)) $OP($C(op)) %$i%"
      }
      incr i
    }

    lappend ret idxstr [join $elist " AND "]
    #puts "xBestIndex: $ret"
    return $ret
  }

  xFilter {
    foreach {idxnum idxstr arglist} $args {}
    set i 0
    set ee $idxstr
    foreach a $arglist {
      if {[string is double $a]==0} {
        set a "'[string map {' ''} $a]'"
      }
      set ee [string map [list "%$i%" $a] $ee]
      incr i
    }
    set ee [string map [list "'" "''"] $ee]

    set ret [list sql "SELECT 1, 'a', 'b', 'c', 'd', '$ee'"]
    #puts "xFilter: $ret"
    return $ret
  }
}

return {}
